$ErrorActionPreference='Stop'
$b=$PSScriptRoot;$r=Join-Path $b 'repo';$design='RobWork/doc/industrial-robot-design/';$base='b83fa7a3fc8ff233e56736adabd53f11c914dbad';$rel=$design+'reuse/functions/project.json'
function HashText([string]$t){$t=($t.TrimStart([char]0xfeff) -replace "`r`n","`n").TrimEnd("`n")+"`n";[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($t))).ToLowerInvariant()}
$old=((& git -C $r show "${base}:$rel") -join "`n")|ConvertFrom-Json;$new=Get-Content (Join-Path $r $rel) -Raw|ConvertFrom-Json
$oldRow=$old.functions|Where-Object {$_.functionId -ceq 'project.Codec.anonymous.requirePathField'};$newRow=$new.functions|Where-Object {$_.functionId -ceq 'project.Codec.anonymous.requirePathField'}
$rework=Get-Content (Join-Path $r ($design+'traceability/reuse/REUSE-T01/batch14-rework.json')) -Raw|ConvertFrom-Json
$descriptionMatches=($rework.before -ceq $oldRow.differences -and $rework.after -ceq $newRow.differences)
$oldRow.differences=$newRow.differences;$onlyExpectedMatrixChange=(($old|ConvertTo-Json -Depth 100 -Compress) -ceq ($new|ConvertTo-Json -Depth 100 -Compress))
$hashes=@();foreach($s in $newRow.sources){$lines=([IO.File]::ReadAllText((Join-Path $r $s.path)).TrimStart([char]0xfeff) -replace "`r`n","`n") -split "`n";$actual=HashText ($lines[($s.startLine-1)..($s.endLine-1)] -join "`n");$hashes += [pscustomobject]@{kind='source';path=$s.path;expected=$s.sha256;actual=$actual;pass=($actual -ceq $s.sha256)}}
foreach($k in @('inputs','auditEvidence')){foreach($s in $newRow.$k){$actual=HashText ([IO.File]::ReadAllText((Join-Path $r $s.path)));$hashes += [pscustomobject]@{kind=$k;path=$s.path;expected=$s.sha256;actual=$actual;pass=($actual -ceq $s.sha256)}}}
$hashes|ConvertTo-Json -Depth 10|Set-Content (Join-Path $b 'hash-checks.json') -Encoding utf8
$originalRoot='C:/Users/zgl18/AppData/Local/Temp/ird-accept-b14-5af9e91d1c154382836f67eee11b94b6';$arc=Join-Path $r ($design+'traceability/acceptance/REUSE-T01-batch14-r1-20261023');$archives=@()
foreach($f in (Get-ChildItem -LiteralPath $arc -File)){$src=Join-Path $originalRoot $f.Name;$raw=$false;$nl=$false;$exists=Test-Path -LiteralPath $src;if($exists){$raw=((Get-FileHash -LiteralPath $src -Algorithm SHA256).Hash -ceq (Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash);$nl=(([IO.File]::ReadAllText($src) -replace "`r`n","`n") -ceq ([IO.File]::ReadAllText($f.FullName) -replace "`r`n","`n"))};$archives+=[pscustomobject]@{file=$f.Name;original=$src;rawMatch=$raw;newlineOnly=(!$raw -and $nl);pass=($raw -or $nl)}}
$archives|ConvertTo-Json -Depth 10|Set-Content (Join-Path $b 'archive-checks.json') -Encoding utf8
$original=Get-Content (Join-Path $arc 'acceptance.json') -Raw|ConvertFrom-Json;$originalFailPreserved=($original.result -ceq 'FAIL' -and $original.reviewedCommit -ceq $base -and @($original.findings|Where-Object {$_.id -ceq 'B14-P2-01' -and $_.status -ceq 'OPEN'}).Count -eq 1)
$files=@(& git -C $r diff --name-only HEAD^ HEAD);$files|Set-Content (Join-Path $b 'changed-files.log');$exclusions=@($files|Where-Object {$_ -match '/traceability/acceptance/.+\.log$'});$included=@($files|Where-Object {$_ -notin $exclusions});$exclusions|Set-Content (Join-Path $b 'diff-check-exclusions.log')
& git -C $r diff --check HEAD^ HEAD -- @included *> (Join-Path $b 'scoped-diff-check.log');$diffExit=$LASTEXITCODE;$diffExit|Set-Content (Join-Path $b 'scoped-diff-check.exit.txt')
& git -C $r diff --name-only $base HEAD -- RobWork/RobWorkStudio/src RobWork/RobWork/src RobWork/RobWorkSim/src vcpkg *> (Join-Path $b 'product-upstream-diff.log')
& git -C $r status --porcelain=v1 *> (Join-Path $b 'final-status.log')
$facts=[ordered]@{reviewedCommit=((& git -C $r rev-parse HEAD).Trim());comparisonBase=$base;descriptionMatches=$descriptionMatches;onlyExpectedMatrixChange=$onlyExpectedMatrixChange;rowPending=($newRow.decision -ceq 'pending' -and $newRow.status -ceq 'pending');hashChecks=$hashes.Count;hashFailures=@($hashes|Where-Object {!$_.pass}).Count;reworkSourceMatches=(($rework.source|ConvertTo-Json -Depth 10 -Compress) -ceq ($newRow.sources|ConvertTo-Json -Depth 10 -Compress));archiveFiles=$archives.Count;archiveRawMatches=@($archives|Where-Object {$_.rawMatch}).Count;archiveNewlineOnly=@($archives|Where-Object {$_.newlineOnly}).Count;archiveMismatches=@($archives|Where-Object {!$_.pass}).Count;originalFailPreserved=$originalFailPreserved;scopedDiffCheckExit=$diffExit;sourceDiffEmpty=((Get-Item (Join-Path $b 'product-upstream-diff.log')).Length -eq 0);clean=((Get-Item (Join-Path $b 'final-status.log')).Length -eq 0)}
$facts|ConvertTo-Json -Depth 10|Tee-Object (Join-Path $b 'facts.json')
